def get_stories(story_type=None, num_stories=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0367000" if __import__("os").path.isdir("./environment_mix/0367000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_rfc3339(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _log_request(status, error_code=None, meta=None):
        fn = "request_logs.json"
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "get_stories",
            "timestamp": _now_iso(),
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - started) * 1000),
            "meta": meta or {}
        })
        _save(fn, logs)

    def _rate_limit_check():
        fn = "request_logs.json"
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        window_s = 60
        max_req = 120
        cnt = 0
        for r in reversed(logs[-5000:]):
            ts = _parse_rfc3339(r.get("timestamp"))
            if not ts:
                continue
            if (now - ts).total_seconds() <= window_s:
                cnt += 1
            else:
                break
        if cnt >= max_req:
            return _err("RATE_LIMIT", "Rate limit exceeded", retry_after_seconds=5, limit=max_req, window_seconds=window_s)
        return None

    rl = _rate_limit_check()
    if rl:
        _log_request("error", "RATE_LIMIT")
        return rl

    # validation: be permissive—accept any string; if it's not a known feed type, return empty list (not error)
    if story_type is not None and not isinstance(story_type, str):
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "story_type must be a string")
    story_type_norm = (story_type or "").strip()
    allowed = {"top", "new", "ask_hn", "show_hn"}
    if story_type_norm not in allowed:
        # relaxed behavior: do not error; return empty
        if num_stories is None:
            num_stories = 10
        if not isinstance(num_stories, int):
            _log_request("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "num_stories must be an integer")
        if num_stories <= 0:
            _log_request("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "num_stories must be a positive integer")
        num_stories = max(1, min(100, num_stories))
        _log_request("ok", meta={"story_type": story_type_norm, "returned": 0})
        return {"stories": [], "story_type": story_type_norm, "count": 0}

    if num_stories is None:
        num_stories = 10
    if not isinstance(num_stories, int):
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "num_stories must be an integer")
    if num_stories <= 0:
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "num_stories must be a positive integer")
    num_stories = max(1, min(100, num_stories))

    feeds = _load("hn_story_feeds.json")
    if not isinstance(feeds, list):
        feeds = []
    items = _load("hn_items.json")
    if not isinstance(items, list):
        items = []

    # Choose latest current snapshot (if multiple) for this feed_type
    current = [r for r in feeds if isinstance(r, dict) and r.get("feed_type") == story_type_norm and r.get("status") == "current"]
    if current:
        def _snap_key(r):
            dt = _parse_rfc3339(r.get("snapshot_at")) or _parse_rfc3339(r.get("updated_at")) or _parse_rfc3339(r.get("created_at"))
            return dt or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        current.sort(key=_snap_key, reverse=True)
        snap_at = current[0].get("snapshot_at")
        snap_rows = [r for r in current if r.get("snapshot_at") == snap_at]
    else:
        snap_rows = []

    # If no snapshot, return empty (offline service; upstream fetch not implemented here)
    if not snap_rows:
        _log_request("ok", meta={"story_type": story_type_norm, "returned": 0, "reason": "no_current_snapshot"})
        return {"stories": [], "story_type": story_type_norm, "count": 0}

    snap_rows.sort(key=lambda r: (r.get("rank") if isinstance(r.get("rank"), int) else 10**9, str(r.get("id", ""))))
    story_ids = [r.get("story_hn_item_id") for r in snap_rows if isinstance(r.get("story_hn_item_id"), int)]
    story_ids = story_ids[:num_stories]

    # index items by hn_item_id (story only), and filter out non-active
    item_by_hn = {}
    for it in items:
        if not isinstance(it, dict):
            continue
        if it.get("item_type") != "story":
            continue
        hnid = it.get("hn_item_id")
        if isinstance(hnid, int):
            item_by_hn[hnid] = it

    out = []
    for hnid in story_ids:
        it = item_by_hn.get(hnid)
        if not it:
            continue
        if it.get("status") != "active":
            continue
        out.append(it)

    _log_request("ok", meta={"story_type": story_type_norm, "requested": num_stories, "returned": len(out)})
    return {"stories": out, "story_type": story_type_norm, "count": len(out)}

def get_user_info(user_name, num_stories=None, **_extra):
    import json, os, datetime, time, uuid, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0367000" if __import__("os").path.isdir("./environment_mix/0367000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    started = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_rfc3339(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                base = s[:-1]
                dt = datetime.datetime.fromisoformat(base)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _load_rows(file_name):
        data = _load(file_name)
        if isinstance(data, dict) and isinstance(data.get("rows"), list):
            return data["rows"]
        if isinstance(data, list):
            return data
        return []

    def _save_rows(file_name, rows):
        existing = _load(file_name)
        if isinstance(existing, dict):
            existing["rows"] = rows
            _save(file_name, existing)
        else:
            _save(file_name, rows)

    def _log_request(status, error_code=None, meta=None):
        fn = "request_logs.json"
        logs = _ensure_list(_load(fn))
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "get_user_info",
            "timestamp": _now_iso(),
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - started) * 1000),
            "meta": meta or {}
        })
        _save(fn, logs)

    def _rate_limit_check():
        # Simple shared rate limit: 120 requests/minute across all endpoints
        fn = "request_logs.json"
        logs = _ensure_list(_load(fn))
        now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        window_s = 60
        max_req = 120
        cnt = 0
        for r in reversed(logs[-5000:]):
            ts = _parse_rfc3339(r.get("timestamp"))
            if not ts:
                continue
            if (now - ts).total_seconds() <= window_s:
                cnt += 1
            else:
                break
        if cnt >= max_req:
            return _err("RATE_LIMIT", "Rate limit exceeded", retry_after_seconds=5, limit=max_req, window_seconds=window_s)
        return None

    # Validate inputs
    if not isinstance(user_name, str) or len(user_name.strip()) < 1 or len(user_name.strip()) > 64:
        rl = _rate_limit_check()
        if rl:
            _log_request("error", rl["error"]["code"], {"user_name": user_name, "num_stories": num_stories})
            return rl
        err = _err("VALIDATION_ERROR", "user_name must be a non-empty string of length 1..64")
        _log_request("error", err["error"]["code"], {"user_name": user_name, "num_stories": num_stories})
        return err

    if num_stories is None:
        num = 10
    else:
        if not isinstance(num_stories, int):
            rl = _rate_limit_check()
            if rl:
                _log_request("error", rl["error"]["code"], {"user_name": user_name, "num_stories": num_stories})
                return rl
            err = _err("VALIDATION_ERROR", "num_stories must be an integer")
            _log_request("error", err["error"]["code"], {"user_name": user_name, "num_stories": num_stories})
            return err
        num = num_stories
    # Clamp regardless of client input (business rule)
    if num < 1:
        num = 1
    if num > 100:
        num = 100

    rl = _rate_limit_check()
    if rl:
        _log_request("error", rl["error"]["code"], {"user_name": user_name, "num_stories": num})
        return rl

    users = _load_rows("hn_users.json")
    items = _load_rows("hn_items.json")

    uname = user_name.strip()
    user_row = None
    for u in users:
        if isinstance(u, dict) and u.get("username") == uname:
            user_row = u
            break

    # If missing, we could "fetch upstream" per business rules, but offline datastore: return NOT_FOUND.
    if not user_row:
        err = _err("NOT_FOUND", "User not found")
        _log_request("error", err["error"]["code"], {"user_name": uname, "num_stories": num})
        return err

    # Filter active stories by this user, ordered by time_posted_at desc
    uid = user_row.get("id")
    def _time_key(r):
        dt = _parse_rfc3339(r.get("time_posted_at"))
        return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    user_stories = []
    for it in items:
        if not isinstance(it, dict):
            continue
        if it.get("item_type") != "story":
            continue
        if it.get("status") != "active":
            continue
        if uid is not None and it.get("by_user_id") != uid:
            continue
        user_stories.append(it)

    user_stories.sort(key=_time_key, reverse=True)
    user_stories = user_stories[:num]

    body = {
        "user": user_row,
        "stories": user_stories,
        "meta": {
            "user_name": uname,
            "returned_stories": len(user_stories),
            "requested_num_stories": num
        }
    }
    _log_request("success", None, {"user_name": uname, "num_stories": num, "returned": len(user_stories)})
    return body

def search_stories(query, search_by_date=None, num_results=None, **_extra):
    import json, os, datetime, time, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0367000" if __import__("os").path.isdir("./environment_mix/0367000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    request_logs_file = "request_logs.json"
    logs = _load(request_logs_file)
    if not isinstance(logs, list):
        logs = []

    def _parse_ts(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    # Rate limit
    window_s = 60
    limit = 120
    cutoff = now_dt - datetime.timedelta(seconds=window_s)
    recent = 0
    for r in logs:
        ts = _parse_ts(r.get("timestamp"))
        if ts and ts >= cutoff:
            recent += 1
    if recent >= limit:
        logs.append({
            "id": "req_" + hashlib.sha256((now + "|search_stories|rl|" + str(len(logs))).encode("utf-8")).hexdigest()[:16],
            "endpoint": "search_stories",
            "timestamp": now,
            "status": "error",
            "error_code": "RATE_LIMIT",
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save(request_logs_file, logs)
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # validation
    if not isinstance(query, str) or len(query.strip()) < 1:
        logs.append({
            "id": "req_" + hashlib.sha256((now + "|search_stories|val|" + str(len(logs))).encode("utf-8")).hexdigest()[:16],
            "endpoint": "search_stories",
            "timestamp": now,
            "status": "error",
            "error_code": "VALIDATION_ERROR",
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save(request_logs_file, logs)
        return _err("VALIDATION_ERROR", "query must be a non-empty string")

    if search_by_date is None:
        search_by_date = False
    if not isinstance(search_by_date, bool):
        logs.append({
            "id": "req_" + hashlib.sha256((now + "|search_stories|valb|" + str(len(logs))).encode("utf-8")).hexdigest()[:16],
            "endpoint": "search_stories",
            "timestamp": now,
            "status": "error",
            "error_code": "VALIDATION_ERROR",
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save(request_logs_file, logs)
        return _err("VALIDATION_ERROR", "search_by_date must be a boolean")

    if num_results is None:
        num_results = 10
    if not isinstance(num_results, int) or num_results <= 0:
        logs.append({
            "id": "req_" + hashlib.sha256((now + "|search_stories|vali|" + str(len(logs))).encode("utf-8")).hexdigest()[:16],
            "endpoint": "search_stories",
            "timestamp": now,
            "status": "error",
            "error_code": "VALIDATION_ERROR",
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save(request_logs_file, logs)
        return _err("VALIDATION_ERROR", "num_results must be a positive integer")
    if num_results > 100:
        num_results = 100
    if num_results < 1:
        num_results = 1

    search_queries = _load("search_queries.json")
    search_results = _load("search_results.json")
    hn_items = _load("hn_items.json")
    if not isinstance(search_queries, list):
        search_queries = []
    if not isinstance(search_results, list):
        search_results = []
    if not isinstance(hn_items, list):
        hn_items = []

    def _gen_id(prefix):
        return prefix + "_" + hashlib.sha256((prefix + "|" + now + "|" + str(random.random())).encode("utf-8")).hexdigest()[:16]

    def _normalize_hash(q, sbd, lim):
        norm = " ".join(q.strip().lower().split())
        key = f"q={norm}|date={int(bool(sbd))}|lim={int(lim)}"
        return hashlib.sha256(key.encode("utf-8")).hexdigest()

    norm_hash = _normalize_hash(query, search_by_date, num_results)

    def _find_active_query(h):
        for sq in search_queries:
            if sq.get("normalized_query_hash") == h and sq.get("status") in ("queued", "running", "completed"):
                return sq
        return None

    def _is_expired(sq):
        exp = _parse_ts(sq.get("expires_at"))
        if exp is None:
            return True
        return exp <= now_dt

    # reuse if possible
    sq = _find_active_query(norm_hash)
    if sq and sq.get("status") == "completed" and not _is_expired(sq):
        sid = sq.get("id")
        results = [r for r in search_results if r.get("search_query_id") == sid]
        results.sort(key=lambda r: (r.get("rank") if isinstance(r.get("rank"), int) else 10**9, r.get("id") or ""))
        results = results[:num_results]

        # join to stories; enforce active only
        out = []
        for r in results:
            hn_id = r.get("story_hn_item_id")
            story = None
            for it in hn_items:
                if it.get("hn_item_id") == hn_id and it.get("item_type") == "story":
                    story = it
                    break
            if not story or story.get("status") != "active":
                continue
            out.append({"result": r, "story": story})

        resp = {
            "query": query,
            "search_by_date": search_by_date,
            "num_requested": num_results,
            "search_query": sq,
            "hits": out,
            "meta": {
                "returned": len(out),
                "cached": True,
            },
        }
        logs.append({
            "id": "req_" + hashlib.sha256((now + "|search_stories|ok_cached|" + str(len(logs))).encode("utf-8")).hexdigest()[:16],
            "endpoint": "search_stories",
            "timestamp": now,
            "status": "ok",
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save(request_logs_file, logs)
        return resp

    # If an existing completed query is expired, mark expired (legal transition) and create new
    if sq and sq.get("status") == "completed" and _is_expired(sq):
        sq["status"] = "expired"
        sq["updated_at"] = now
        _save("search_queries.json", search_queries)
        sq = None

    # Create new query if needed; enforce uniqueness for active statuses by normalized hash
    if sq is None:
        sq = {
            "id": _gen_id("sq"),
            "query_text": query,
            "search_by_date": bool(search_by_date),
            "requested_num_results": int(num_results),
            "normalized_query_hash": norm_hash,
            "status": "queued",
            "executed_at": None,
            "expires_at": None,
            "error_message": None,
            "created_at": now,
            "updated_at": now,
        }
        search_queries.append(sq)
        _save("search_queries.json", search_queries)

    # Execute search: queued->running->completed/failed
    if sq.get("status") not in ("queued", "running"):
        # cannot execute failed/expired
        logs.append({
            "id": "req_" + hashlib.sha256((now + "|search_stories|badstate|" + str(len(logs))).encode("utf-8")).hexdigest()[:16],
            "endpoint": "search_stories",
            "timestamp": now,
            "status": "error",
            "error_code": "INVALID_TRANSITION",
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save(request_logs_file, logs)
        return _err("INVALID_TRANSITION", "Search query is not executable in its current state")

    # transition to running
    if sq.get("status") == "queued":
        sq["status"] = "running"
        sq["updated_at"] = now
        _save("search_queries.json", search_queries)

    # Offline "upstream search": match query tokens against title/text_html in local active stories.
    try:
        tokens = [t for t in "".join([c.lower() if (c.isalnum() or c.isspace()) else " " for c in query]).split() if t]
    except Exception:
        tokens = query.strip().lower().split()

    stories = [it for it in hn_items if it.get("item_type") == "story" and it.get("status") == "active"]
    scored = []
    for it in stories:
        text = ((it.get("title") or "") + " " + (it.get("text_html") or "")).lower()
        if not tokens:
            match = True
            score = 0.0
        else:
            hits = sum(1 for tok in tokens if tok in text)
            match = hits > 0
            score = float(hits)
        if not match:
            continue
        # tie breakers
        pts = it.get("score_points") if isinstance(it.get("score_points"), int) else 0
        com = it.get("num_comments") if isinstance(it.get("num_comments"), int) else 0
        tsp = _parse_ts(it.get("time_posted_at")) or datetime.datetime.min
        if search_by_date:
            key = (tsp, score, pts, com)
        else:
            key = (score, pts, com, tsp)
        scored.append((key, it))

    # Order
    if search_by_date:
        scored.sort(key=lambda x: (x[0][0], x[0][1], x[0][2], x[0][3]), reverse=True)
    else:
        scored.sort(key=lambda x: (x[0][0], x[0][1], x[0][2], x[0][3]), reverse=True)

    # If nothing in local store, we cannot reach upstream in offline mode => fail
    if len(scored) == 0:
        sq["status"] = "failed"
        sq["error_message"] = "Upstream search unavailable and no local data matches"
        sq["updated_at"] = now
        _save("search_queries.json", search_queries)

        logs.append({
            "id": "req_" + hashlib.sha256((now + "|search_stories|upfail|" + str(len(logs))).encode("utf-8")).hexdigest()[:16],
            "endpoint": "search_stories",
            "timestamp": now,
            "status": "error",
            "error_code": "UPSTREAM_UNAVAILABLE",
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save(request_logs_file, logs)
        return _err("UPSTREAM_UNAVAILABLE", "Upstream Hacker News source unavailable")

    # persist results (replace existing for this query id if any)
    sid = sq.get("id")
    search_results = [r for r in search_results if r.get("search_query_id") != sid]

    top = scored[:num_results]
    rank = 1
    for _key, it in top:
        hn_id = it.get("hn_item_id")
        if not isinstance(hn_id, int):
            continue
        search_results.append({
            "id": _gen_id("sr"),
            "search_query_id": sid,
            "story_hn_item_id": hn_id,
            "rank": rank,
            "match_score": None,
            "snippet": None,
            "created_at": now,
            "updated_at": now,
        })
        rank += 1

    # complete query
    sq["status"] = "completed"
    sq["executed_at"] = now
    sq["expires_at"] = (now_dt + datetime.timedelta(minutes=30)).replace(microsecond=0).isoformat() + "Z"
    sq["error_message"] = None
    sq["updated_at"] = now

    _save("search_results.json", search_results)
    _save("search_queries.json", search_queries)

    # Build response
    # Join and ensure active only (already active)
    results = [r for r in search_results if r.get("search_query_id") == sid]
    results.sort(key=lambda r: (r.get("rank") if isinstance(r.get("rank"), int) else 10**9, r.get("id") or ""))
    hits = []
    for r in results:
        hn_id = r.get("story_hn_item_id")
        story = None
        for it in hn_items:
            if it.get("hn_item_id") == hn_id and it.get("item_type") == "story":
                story = it
                break
        if not story or story.get("status") != "active":
            continue
        hits.append({"result": r, "story": story})

    resp = {
        "query": query,
        "search_by_date": search_by_date,
        "num_requested": num_results,
        "search_query": sq,
        "hits": hits,
        "meta": {"returned": len(hits), "cached": False},
    }

    logs.append({
        "id": "req_" + hashlib.sha256((now + "|search_stories|ok|" + str(len(logs))).encode("utf-8")).hexdigest()[:16],
        "endpoint": "search_stories",
        "timestamp": now,
        "status": "ok",
        "latency_ms": int((time.time() - t0) * 1000),
    })
    _save(request_logs_file, logs)
    return resp

def get_story_info(story_id=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0367000" if __import__("os").path.isdir("./environment_mix/0367000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    started = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_rfc3339(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1])
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _load_rows(file_name):
        data = _load(file_name)
        if isinstance(data, dict) and isinstance(data.get("rows"), list):
            return data["rows"]
        if isinstance(data, list):
            return data
        return []

    def _log_request(status, error_code=None, meta=None):
        fn = "request_logs.json"
        logs = _ensure_list(_load(fn))
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "get_story_info",
            "timestamp": _now_iso(),
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - started) * 1000),
            "meta": meta or {}
        })
        _save(fn, logs)

    def _rate_limit_check():
        fn = "request_logs.json"
        logs = _ensure_list(_load(fn))
        now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        window_s = 60
        max_req = 120
        cnt = 0
        for r in reversed(logs[-5000:]):
            ts = _parse_rfc3339(r.get("timestamp"))
            if not ts:
                continue
            if (now - ts).total_seconds() <= window_s:
                cnt += 1
            else:
                break
        if cnt >= max_req:
            return _err("RATE_LIMIT", "Rate limit exceeded", retry_after_seconds=5, limit=max_req, window_seconds=window_s)
        return None

    # Validate input
    if story_id is None or not isinstance(story_id, int) or story_id <= 0:
        rl = _rate_limit_check()
        if rl:
            _log_request("error", rl["error"]["code"], {"story_id": story_id})
            return rl
        err = _err("VALIDATION_ERROR", "story_id must be a positive integer")
        _log_request("error", err["error"]["code"], {"story_id": story_id})
        return err

    rl = _rate_limit_check()
    if rl:
        _log_request("error", rl["error"]["code"], {"story_id": story_id})
        return rl

    items = _load_rows("hn_items.json")

    story = None
    for it in items:
        if not isinstance(it, dict):
            continue
        if it.get("hn_item_id") == story_id and it.get("item_type") == "story":
            story = it
            break

    # Offline datastore: if not present, NOT_FOUND (no upstream fetch available here)
    if not story:
        err = _err("NOT_FOUND", "Story not found")
        _log_request("error", err["error"]["code"], {"story_id": story_id})
        return err

    # Filter out non-active items per rule
    if story.get("status") != "active":
        err = _err("NOT_FOUND", "Story not found")
        _log_request("error", err["error"]["code"], {"story_id": story_id, "story_status": story.get("status")})
        return err

    # Collect comments for this story (active only)
    comments = []
    for it in items:
        if not isinstance(it, dict):
            continue
        if it.get("item_type") != "comment":
            continue
        if it.get("status") != "active":
            continue
        if it.get("root_story_hn_item_id") == story_id:
            comments.append(it)

    # Build a thread tree using parent_hn_item_id
    by_hnid = {}
    for c in comments:
        hnid = c.get("hn_item_id")
        if isinstance(hnid, int):
            by_hnid[hnid] = c

    children = {}
    for c in comments:
        parent = c.get("parent_hn_item_id")
        if not isinstance(parent, int):
            continue
        children.setdefault(parent, []).append(c.get("hn_item_id"))

    def _comment_node(cid, visiting=None):
        if visiting is None:
            visiting = set()
        if cid in visiting:
            # break cycles defensively
            return {"comment": by_hnid.get(cid), "replies": []}
        visiting.add(cid)
        c = by_hnid.get(cid)
        reply_ids = children.get(cid, [])
        reply_nodes = []
        for rid in reply_ids:
            if rid in by_hnid:
                reply_nodes.append(_comment_node(rid, visiting))
        visiting.remove(cid)
        return {"comment": c, "replies": reply_nodes}

    # Top-level comments are those whose parent is the story itself
    top_ids = [cid for cid in children.get(story_id, []) if cid in by_hnid]

    # Stable ordering: by time_posted_at asc if present, else by hn_item_id asc
    def _c_sort_key(cid):
        c = by_hnid.get(cid, {})
        dt = _parse_rfc3339(c.get("time_posted_at"))
        return (dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc), cid)

    top_ids.sort(key=_c_sort_key)

    thread = [_comment_node(cid) for cid in top_ids]

    body = {
        "story": story,
        "comments": comments,
        "thread": thread,
        "meta": {
            "story_id": story_id,
            "returned_comments": len(comments),
            "top_level_comments": len(top_ids)
        }
    }
    _log_request("success", None, {"story_id": story_id, "comments": len(comments)})
    return body

def get_item(hn_item_id, include_text_html=None, include_inactive=None, **_extra):
    import json, os, datetime, time, urllib.request, urllib.error

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0367000" if __import__("os").path.isdir("./environment_mix/0367000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _clamp(n, lo, hi):
        return max(lo, min(hi, n))

    def _log(status, endpoint, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status,
            "timestamp": _now(),
            "meta": meta or {},
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _check_rate_limit(endpoint):
        # Sliding window: 60s, max 120 requests
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        window_s = 60
        max_req = 120
        cnt = 0
        for r in reversed(logs[-2000:]):
            ts = _parse_rfc3339(r.get("timestamp"))
            if not ts:
                continue
            if (now - ts).total_seconds() <= window_s:
                cnt += 1
            else:
                break
        if cnt >= max_req:
            return _err("RATE_LIMIT", "Rate limit exceeded", retry_after_seconds=5, limit=max_req, window_seconds=window_s, endpoint=endpoint)
        return None

    endpoint = "get_item"
    t0 = time.time()

    # Validate inputs
    if not isinstance(hn_item_id, int) or isinstance(hn_item_id, bool) or hn_item_id <= 0:
        _log("error", endpoint, {"latency_ms": int((time.time() - t0) * 1000), "code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "hn_item_id must be a positive integer")

    if include_text_html is None:
        include_text_html = True
    if include_inactive is None:
        include_inactive = False
    if not isinstance(include_text_html, bool):
        _log("error", endpoint, {"latency_ms": int((time.time() - t0) * 1000), "code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "include_text_html must be a boolean")
    if not isinstance(include_inactive, bool):
        _log("error", endpoint, {"latency_ms": int((time.time() - t0) * 1000), "code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "include_inactive must be a boolean")

    rl = _check_rate_limit(endpoint)
    if rl:
        _log("error", endpoint, {"latency_ms": int((time.time() - t0) * 1000), "code": rl["error"]["code"]})
        return rl

    items = _load("hn_items.json")
    if not isinstance(items, list):
        items = []

    # Freshness policy
    FRESH_FOR_SECONDS = 15 * 60
    now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _is_fresh(row):
        ls = _parse_rfc3339(row.get("last_synced_at"))
        if not ls:
            return False
        return (now_dt - ls).total_seconds() <= FRESH_FOR_SECONDS

    def _filter_visibility(row):
        st = row.get("status")
        if include_inactive:
            return True
        return st == "active"

    existing = None
    for r in items:
        if r.get("hn_item_id") == hn_item_id:
            existing = r
            break

    # If present and fresh enough, return cached
    if existing and _is_fresh(existing):
        if not _filter_visibility(existing):
            _log("error", endpoint, {"latency_ms": int((time.time() - t0) * 1000), "code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Item not found")
        out = dict(existing)
        if not include_text_html:
            out.pop("text_html", None)
        _log("ok", endpoint, {"latency_ms": int((time.time() - t0) * 1000), "cached": True})
        return {"item": out, "cached": True}

    # Fetch upstream
    url = f"https://hacker-news.firebaseio.com/v0/item/{hn_item_id}.json"
    try:
        with urllib.request.urlopen(url, timeout=8) as resp:
            raw = resp.read().decode("utf-8")
            data = json.loads(raw) if raw else None
    except (urllib.error.URLError, urllib.error.HTTPError, TimeoutError, json.JSONDecodeError):
        _log("error", endpoint, {"latency_ms": int((time.time() - t0) * 1000), "code": "UPSTREAM_UNAVAILABLE"})
        return _err("UPSTREAM_UNAVAILABLE", "Upstream cannot be reached")

    if not data:
        _log("error", endpoint, {"latency_ms": int((time.time() - t0) * 1000), "code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Item not found")

    # Map upstream to schema
    upstream_type = data.get("type")
    if upstream_type not in ("story", "comment"):
        # Ignore unsupported types as not found for this service
        _log("error", endpoint, {"latency_ms": int((time.time() - t0) * 1000), "code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Item not found")

    status = "active"
    if data.get("deleted") is True:
        status = "deleted"
    elif data.get("dead") is True:
        status = "dead"

    # Enforce constraints around parent/root for comment vs story
    parent_id = data.get("parent")
    if upstream_type == "comment" and (not isinstance(parent_id, int) or parent_id <= 0):
        # Upstream should have parent; treat as invalid upstream row -> not found
        _log("error", endpoint, {"latency_ms": int((time.time() - t0) * 1000), "code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Item not found")
    if upstream_type == "story":
        parent_id = None

    # Resolve / upsert user if provided
    users = _load("hn_users.json")
    if not isinstance(users, list):
        users = []

    by_user_id = None
    by_username = data.get("by")
    if isinstance(by_username, str) and by_username.strip():
        uname = by_username.strip()
        # validate username constraints
        if 1 <= len(uname) <= 64:
            urow = None
            for u in users:
                if u.get("username") == uname:
                    urow = u
                    break
            now_iso = _now()
            if urow is None:
                # create unknown user shell; status unknown -> can transition later
                new_uid = f"usr_{int(time.time()*1000)}_{len(users)+1}"
                urow = {
                    "id": new_uid,
                    "username": uname,
                    "hn_user_id": None,
                    "created_at_hn": None,
                    "karma": None,
                    "about_html": None,
                    "status": "unknown",
                    "last_synced_at": None,
                    "created_at": now_iso,
                    "updated_at": now_iso,
                }
                users.append(urow)
                _save("hn_users.json", users)
            by_user_id = urow.get("id")

    # Determine root_story_hn_item_id for comments
    root_story_id = None
    if upstream_type == "comment":
        # If upstream provides "story" field (rare), use it; else compute from cached parent chain if possible
        rs = data.get("story")
        if isinstance(rs, int) and rs > 0:
            root_story_id = rs
        else:
            # Try to infer: if parent is story in cache -> parent; if parent comment has root -> reuse.
            parent_row = None
            for r in items:
                if r.get("hn_item_id") == parent_id:
                    parent_row = r
                    break
            if parent_row:
                if parent_row.get("item_type") == "story":
                    root_story_id = parent_row.get("hn_item_id")
                elif parent_row.get("item_type") == "comment":
                    root_story_id = parent_row.get("root_story_hn_item_id")
            # If still unknown, leave null; allowed by schema (nullable)

    now_iso = _now()
    mapped = {
        "hn_item_id": hn_item_id,
        "item_type": upstream_type,
        "story_subtype": None,
        "title": data.get("title") if upstream_type == "story" else None,
        "url": data.get("url") if upstream_type == "story" else None,
        "text_html": data.get("text"),
        "by_user_id": by_user_id,
        "time_posted_at": _iso(datetime.datetime.fromtimestamp(int(data.get("time", int(time.time()))), tz=datetime.timezone.utc)),
        "parent_hn_item_id": parent_id if upstream_type == "comment" else None,
        "root_story_hn_item_id": root_story_id if upstream_type == "comment" else None,
        "score_points": data.get("score") if isinstance(data.get("score"), int) and data.get("score") >= 0 else None,
        "num_comments": data.get("descendants") if isinstance(data.get("descendants"), int) and data.get("descendants") >= 0 else None,
        "status": status,
        "last_synced_at": now_iso,
    }

    # Upsert into hn_items with constraints
    # unique(hn_item_id)
    row = existing
    if row is None:
        new_id = f"itm_{hn_item_id}"
        row = {
            "id": new_id,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        items.append(row)
    else:
        row["updated_at"] = now_iso

    # Enforce schema constraints: comment implies parent not null; story implies parent null; root_story only for comment
    if mapped["item_type"] == "comment" and mapped["parent_hn_item_id"] is None:
        _log("error", endpoint, {"latency_ms": int((time.time() - t0) * 1000), "code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Item not found")
    if mapped["item_type"] == "story" and mapped["parent_hn_item_id"] is not None:
        _log("error", endpoint, {"latency_ms": int((time.time() - t0) * 1000), "code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Item not found")
    if mapped["story_subtype"] is not None and mapped["item_type"] != "story":
        _log("error", endpoint, {"latency_ms": int((time.time() - t0) * 1000), "code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "story_subtype is only allowed for stories")
    if mapped["root_story_hn_item_id"] is not None and mapped["item_type"] != "comment":
        _log("error", endpoint, {"latency_ms": int((time.time() - t0) * 1000), "code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "root_story_hn_item_id is only allowed for comments")

    # Foreign key integrity: by_user_id must exist when present
    if mapped["by_user_id"] is not None:
        if not any(u.get("id") == mapped["by_user_id"] for u in users):
            _log("error", endpoint, {"latency_ms": int((time.time() - t0) * 1000), "code": "CONFLICT"})
            return _err("CONFLICT", "by_user_id references missing user")

    # Write fields
    for k, v in mapped.items():
        row[k] = v
    if "id" not in row or not isinstance(row["id"], str) or not row["id"]:
        row["id"] = f"itm_{hn_item_id}"

    _save("hn_items.json", items)

    # Return with visibility filter
    if not _filter_visibility(row):
        _log("error", endpoint, {"latency_ms": int((time.time() - t0) * 1000), "code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Item not found")

    out = dict(row)
    if not include_text_html:
        out.pop("text_html", None)

    _log("ok", endpoint, {"latency_ms": int((time.time() - t0) * 1000), "cached": False})
    return {"item": out, "cached": False}

