    # Cursor scheme: base64("snapshot_at|id")
    start_after = None
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            _log("error", endpoint, {"latency_ms": int((time.time() - t0) * 1000), "code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string")
        try:
            decoded = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            parts = decoded.split("|", 1)
            if len(parts) != 2:
                raise ValueError("bad cursor")
            c_ts = _parse_rfc3339(parts[0])
            c_id = parts[1]
            if c_ts is None or not c_id:
                raise ValueError("bad cursor")
            start_after = (c_ts, c_id)
        except Exception:
            _log("error", endpoint, {"latency_ms": int((time.time() - t0) * 1000), "code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid cursor")

    feeds = _load("hn_story_feeds.json")
    if not isinstance(feeds, list):
        feeds = []

    # Filter + sort by snapshot_at desc, tie-breaker id desc
    rows = []
    for r in feeds:
        if r.get("feed_type") != feed_type:
            continue
        if r.get("status") != status:
            continue
        ts = _parse_rfc3339(r.get("snapshot_at"))
        if ts is None:
            continue
        if sb_dt is not None and not (ts < sb_dt):
            continue
        rows.append((ts, str(r.get("id", "")), r))

    rows.sort(key=lambda x: (x[0], x[1]), reverse=True)

    if start_after is not None:
        c_ts, c_id = start_after
        filtered = []
        for ts, rid, r in rows:
            # since sorted desc, we skip until strictly less than cursor tuple
            if (ts, rid) < (c_ts, c_id):
                filtered.append((ts, rid, r))
        rows = filtered

    total = len(rows)
    page = rows[:limit]
    out = [dict(r) for _, __, r in page]

    has_more = total > limit
    next_cursor = None
    if has_more and page:
        last_ts, last_id, _ = page[-1]
        token = f"{last_ts.replace(microsecond=0).isoformat().replace('+00:00','Z')}|{last_id}"
        next_cursor = base64.urlsafe_b64encode(token.encode("utf-8")).decode("utf-8")

    _log("ok", endpoint, {"latency_ms": int((time.time() - t0) * 1000), "returned": len(out)})
    return {"snapshots": out, "feed_type": feed_type, "status": status, "limit": limit, "total": total, "has_more": has_more, "next_cursor": next_cursor}

def get_search_query(search_query_id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0367000" if __import__("os").path.isdir("./environment_mix/0367000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _log(status, endpoint, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
                "endpoint": endpoint,
                "status": status,
                "timestamp": _now(),
                "meta": meta or {},
            }
        )
        _save("request_logs.json", logs)

    def _check_rate_limit(endpoint):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        window_s = 60
        max_req = 120
        cnt = 0
        for r in reversed(logs[-2000:]):
            ts = _parse_rfc3339(r.get("timestamp"))
            if not ts:
                continue
            if (now - ts).total_seconds() <= window_s:
                cnt += 1
            else:
                break
        if cnt >= max_req:
            return _err("RATE_LIMIT", "Rate limit exceeded", retry_after_seconds=5, limit=max_req, window_seconds=window_s, endpoint=endpoint)
        return None

    endpoint = "get_search_query"
    t0 = time.time()

    if not isinstance(search_query_id, str) or not search_query_id.strip():
        _log("error", endpoint, {"latency_ms": int((time.time() - t0) * 1000), "code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "search_query_id must be a non-empty string")

    rl = _check_rate_limit(endpoint)
    if rl:
        _log("error", endpoint, {"latency_ms": int((time.time() - t0) * 1000), "code": rl["error"]["code"]})
        return rl

    queries = _load("search_queries.json")
    if not isinstance(queries, list):
        queries = []

    row = None
    for q in queries:
        if q.get("id") == search_query_id:
            row = q
            break

    if row is None:
        _log("error", endpoint, {"latency_ms": int((time.time() - t0) * 1000), "code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Search query not found")

    _log("ok", endpoint, {"latency_ms": int((time.time() - t0) * 1000)})
    return {"search_query": dict(row)}

def list_search_queries(status=None, normalized_query_hash=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0367000" if __import__("os").path.isdir("./environment_mix/0367000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_rfc3339(s):
        if s is None:
            return None
        # relax: accept any string; if not parseable, treat as None (no filter) instead of error
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _log_request(status_, error_code=None, meta=None):
        fn = "request_logs.json"
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "list_search_queries",
            "timestamp": _now_iso(),
            "status": status_,
            "error_code": error_code,
            "latency_ms": int((time.time() - started) * 1000),
            "meta": meta or {}
        })
        _save(fn, logs)

    def _rate_limit_check():
        fn = "request_logs.json"
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        window_s = 60
        max_req = 120
        cnt = 0
        for r in reversed(logs[-5000:]):
            ts = _parse_rfc3339(r.get("timestamp"))
            if not ts:
                continue
            if (now - ts).total_seconds() <= window_s:
                cnt += 1
            else:
                break
        if cnt >= max_req:
            return _err("RATE_LIMIT", "Rate limit exceeded", retry_after_seconds=5, limit=max_req, window_seconds=window_s)
        return None

    rl = _rate_limit_check()
    if rl:
        _log_request("error", "RATE_LIMIT")
        return rl

    # validate enums/types (but be permissive on created_* parsing per audit)
    allowed_status = {"queued", "running", "completed", "failed", "expired"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: queued, running, completed, failed, expired")
    if normalized_query_hash is not None and not isinstance(normalized_query_hash, str):
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "normalized_query_hash must be a string")

    if limit is None:
        limit = 10
    if not isinstance(limit, int):
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit <= 0:
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be a positive integer")
    limit = max(1, min(100, limit))

    dt_after = _parse_rfc3339(created_after)
    dt_before = _parse_rfc3339(created_before)

    # cursor: base64 of created_at|id; if invalid, ignore (permissive)
    cur_created = None
    cur_id = None
    if cursor is not None:
        if isinstance(cursor, str) and cursor:
            try:
                raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
                txt = raw.decode("utf-8", "ignore")
                parts = txt.split("|", 1)
                if len(parts) == 2:
                    cur_created = parts[0]
                    cur_id = parts[1]
            except Exception:
                cur_created = None
                cur_id = None
        else:
            _log_request("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a string")

    rows = _load("search_queries.json")
    if not isinstance(rows, list):
        rows = []

    def _created_key(r):
        dt = _parse_rfc3339(r.get("created_at")) or _parse_rfc3339(r.get("updated_at"))
        return dt or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)

    # filter
    out = []
    for r in rows:
        if not isinstance(r, dict):
            continue
        if status is not None and r.get("status") != status:
            continue
        if normalized_query_hash is not None and r.get("normalized_query_hash") != normalized_query_hash:
            continue
        cdt = _created_key(r)
        if dt_after is not None and cdt < dt_after:
            continue
        if dt_before is not None and cdt >= dt_before:
            continue
        out.append(r)

    # order by created_at desc
    out.sort(key=lambda r: (_created_key(r), str(r.get("id", ""))), reverse=True)

    # apply cursor (start after the cursor item in this ordering)
    if cur_created is not None and cur_id is not None:
        start_idx = 0
        for i, r in enumerate(out):
            if r.get("created_at") == cur_created and r.get("id") == cur_id:
                start_idx = i + 1
                break
        out = out[start_idx:]

    total = len(out)
    page = out[:limit]
    has_more = total > limit

    next_cursor = None
    if has_more and page:
        last = page[-1]
        payload = (str(last.get("created_at", "")) + "|" + str(last.get("id", ""))).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    _log_request("ok", meta={"returned": len(page), "has_more": has_more})
    return {"data": page, "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor}}

def expire_search_query(search_query_id, reason=None, **_extra):
    import json, os, datetime, uuid, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0367000" if __import__("os").path.isdir("./environment_mix/0367000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _get_collection_filename(name):
        mapping = {
            "search_queries": "search_queries.json",
            "usage_logs": "usage_logs.json",
            "api_keys": "api_keys.json",
            "service_credentials": "service_credentials.json",
            "auth_identities": "auth_identities.json",
            "rate_limits": "rate_limits.json",
        }
        return mapping.get(name)

    def _append_usage(endpoint, status, credential_id=None, error_code=None, meta=None, started_at=None):
        fn = _get_collection_filename("usage_logs")
        if not fn:
            return  # schema may omit; no-op
        logs = _load(fn)
        ts = _now_iso()
        latency_ms = None
        if started_at is not None:
            try:
                latency_ms = int((time.time() - started_at) * 1000)
            except Exception:
                latency_ms = None
        row = {
            "id": "ulog_" + uuid.uuid4().hex,
            "service": "hacker_news",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": ts,
            "meta": meta or {},
        }
        if isinstance(logs, list):
            logs.append(row)
            _save(fn, logs)

    def _find_working_credential():
        # Ambient auth: if the datastore has any credential row, we treat caller as authenticated.
        # If the store has explicit api_keys/service_credentials, use one marked active; else allow anonymous.
        for col in ("api_keys.json", "service_credentials.json"):
            path = os.path.join(_DB, col)
            if not os.path.exists(path):
                continue
            rows = _load(col)
            if not isinstance(rows, list):
                continue
            for r in rows:
                if isinstance(r, dict) and r.get("status") in (None, "active", "enabled"):
                    return r.get("id")
        return "ambient"

    def _enforce_rate_limit(credential_id, endpoint):
        # Best-effort: if no usage log collection, skip enforcement.
        fn = _get_collection_filename("usage_logs")
        if not fn:
            return None
        logs = _load(fn)
        if not isinstance(logs, list):
            return None

        now = datetime.datetime.utcnow()
        window_s = 60
        limit = 120  # default service-side limit if none declared in store
        # Allow overrides if a rate_limits collection exists
        rl_fn = _get_collection_filename("rate_limits")
        if rl_fn and os.path.exists(os.path.join(_DB, rl_fn)):
            rl_rows = _load(rl_fn)
            if isinstance(rl_rows, list):
                for r in rl_rows:
                    if not isinstance(r, dict):
                        continue
                    if r.get("service") == "hacker_news" and (r.get("endpoint") in (None, endpoint, "*")):
                        if r.get("credential_id") in (None, credential_id, "*"):
                            try:
                                if isinstance(r.get("window_seconds"), int) and r["window_seconds"] > 0:
                                    window_s = r["window_seconds"]
                                if isinstance(r.get("limit"), int) and r["limit"] > 0:
                                    limit = r["limit"]
                            except Exception:
                                pass
                        break

        cutoff = now - datetime.timedelta(seconds=window_s)
        count = 0
        for ev in logs:
            if not isinstance(ev, dict):
                continue
            if ev.get("service") != "hacker_news":
                continue
            if ev.get("credential_id") != credential_id:
                continue
            if ev.get("endpoint") != endpoint:
                continue
            ts = ev.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                t = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if t >= cutoff:
                count += 1
        if count >= limit:
            return _err("RATE_LIMIT", "Rate limit exceeded", window_seconds=window_s, limit=limit)
        return None

    started = time.time()
    endpoint = "expire_search_query"
    credential_id = _find_working_credential()

    # Rate limit check first (observable service dynamics still logged below)
    rl_err = _enforce_rate_limit(credential_id, endpoint)
    if rl_err:
        _append_usage(endpoint, "error", credential_id=credential_id, error_code=rl_err["error"]["code"], meta={"search_query_id": search_query_id}, started_at=started)
        return rl_err

    # Validate inputs
    if not isinstance(search_query_id, str) or not search_query_id.strip():
        _append_usage(endpoint, "error", credential_id=credential_id, error_code="VALIDATION_ERROR", meta={"field": "search_query_id"}, started_at=started)
        return _err("VALIDATION_ERROR", "search_query_id must be a non-empty string", field="search_query_id")
    if reason is not None and (not isinstance(reason, str) or len(reason) > 256):
        _append_usage(endpoint, "error", credential_id=credential_id, error_code="VALIDATION_ERROR", meta={"field": "reason"}, started_at=started)
        return _err("VALIDATION_ERROR", "reason must be a string of length <= 256", field="reason")

    # Load query
    queries = _load("search_queries.json")
    if not isinstance(queries, list):
        _append_usage(endpoint, "error", credential_id=credential_id, error_code="NOT_FOUND", meta={"search_query_id": search_query_id}, started_at=started)
        return _err("NOT_FOUND", "Search query not found", search_query_id=search_query_id)

    idx = None
    row = None
    for i, q in enumerate(queries):
        if isinstance(q, dict) and q.get("id") == search_query_id:
            idx = i
            row = q
            break

    if row is None:
        _append_usage(endpoint, "error", credential_id=credential_id, error_code="NOT_FOUND", meta={"search_query_id": search_query_id}, started_at=started)
        return _err("NOT_FOUND", "Search query not found", search_query_id=search_query_id)

    status = row.get("status")
    if status != "completed":
        # Contract says refuse to expire queries not in completed.
        # Use CONFLICT for transition not allowed from current state.
        _append_usage(endpoint, "error", credential_id=credential_id, error_code="CONFLICT", meta={"search_query_id": search_query_id, "status": status}, started_at=started)
        return _err("CONFLICT", "Transition not allowed from current state", current_status=status, allowed_from=["completed"], to="expired")

    # Apply transition completed -> expired
    now = _now_iso()
    updated = dict(row)
    updated["status"] = "expired"
    updated["updated_at"] = now
    # Preserve executed_at; set expires_at to now for immediate staleness
    updated["expires_at"] = now
    if reason is not None:
        # store in error_message field? better: append to error_message only if failed; instead keep as observational in a sidecar field if present
        # As schema does not include reason, store it in error_message if empty, prefixed.
        em = updated.get("error_message")
        if em is None or em == "":
            updated["error_message"] = "expired_reason:" + reason
        else:
            updated["error_message"] = str(em)[:900] + " | expired_reason:" + reason

    queries[idx] = updated
    try:
        _save("search_queries.json", queries)
    except Exception:
        _append_usage(endpoint, "error", credential_id=credential_id, error_code="CONFLICT", meta={"search_query_id": search_query_id}, started_at=started)
        return _err("CONFLICT", "Failed to persist search query update")

    _append_usage(endpoint, "ok", credential_id=credential_id, meta={"search_query_id": search_query_id, "from": "completed", "to": "expired"}, started_at=started)
    return {
        "search_query": updated,
        "transition": {"from": "completed", "to": "expired", "at": now},
    }

def get_auth_context(api_key=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0367000" if __import__("os").path.isdir("./environment_mix/0367000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_rfc3339(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _log_request(status, error_code=None, meta=None):
        fn = "request_logs.json"
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "get_auth_context",
            "timestamp": _now_iso(),
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - started) * 1000),
            "meta": meta or {}
        })
        _save(fn, logs)

    def _rate_limit_check():
        fn = "request_logs.json"
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        window_s = 60
        max_req = 120
        cnt = 0
        for r in reversed(logs[-5000:]):
            ts = _parse_rfc3339(r.get("timestamp"))
            if not ts:
                continue
            if (now - ts).total_seconds() <= window_s:
                cnt += 1
            else:
                break
        if cnt >= max_req:
            return _err("RATE_LIMIT", "Rate limit exceeded", retry_after_seconds=5, limit=max_req, window_seconds=window_s)
        return None

    rl = _rate_limit_check()
    if rl:
        _log_request("error", "RATE_LIMIT")
        return rl

    # This service store may not have explicit credential tables; authentication is ambient.
    # If api_key is provided, attempt to resolve it against any client-visible credential value/id
    # present in the datastore. Never compare to hashes/ciphertext.
    users = _load("hn_users.json")
    if not isinstance(users, list):
        users = []

    resolved_identity = None
    used_credential = None

    if api_key is not None:
        if not isinstance(api_key, str) or not api_key.strip():
            _log_request("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "api_key must be a non-empty string when provided")
        k = api_key.strip()

        # In this datastore, the only plausible presented credential is a user id/username.
        # Accept either as the client-visible credential.
        for u in users:
            if not isinstance(u, dict):
                continue
            if u.get("id") == k or u.get("username") == k:
                resolved_identity = u
                used_credential = k
                break

        if resolved_identity is None:
            # search other files for explicit credential tables if they exist in this installation
            candidates = []
            try:
                for fn in os.listdir(_DB):
                    if fn.endswith(".json") and ("key" in fn or "credential" in fn or "api" in fn):
                        candidates.append(fn)
            except Exception:
                candidates = []
            cred_row = None
            for fn in candidates:
                data = _load(fn)
                if not isinstance(data, list):
                    continue
                for row in data:
                    if not isinstance(row, dict):
                        continue
                    for field in ("id", "api_key", "key", "token", "value"):
                        v = row.get(field)
                        if isinstance(v, str) and v == k:
                            cred_row = row
                            break
                    if cred_row is not None:
                        break
                if cred_row is not None:
                    break
            if cred_row is not None:
                resolved_identity = {"credential": cred_row}
                used_credential = k

        if resolved_identity is None:
            _log_request("error", "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Invalid API key")
    else:
        # Ambient auth: pick any active identity usable for the service
        for u in users:
            if isinstance(u, dict) and u.get("status") == "active":
                resolved_identity = u
                break
        if resolved_identity is None and users:
            # fall back to any user row if no active exists
            for u in users:
                if isinstance(u, dict):
                    resolved_identity = u
                    break
        if resolved_identity is None:
            _log_request("error", "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "No valid credentials available")

    # Compute current rate window usage from request_logs
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    window_s = 60
    max_req = 120
    used = 0
    for r in reversed(logs[-5000:]):
        ts = _parse_rfc3339(r.get("timestamp"))
        if not ts:
            continue
        if (now - ts).total_seconds() <= window_s:
            used += 1
        else:
            break

    ctx = {
        "identity": resolved_identity,
        "credential_used": used_credential,
        "entitlements": {
            "service": "hacker_news",
            "scopes": ["read:users", "read:stories", "read:search"],
        },
        "rate_limit": {
            "limit": max_req,
            "window_seconds": window_s,
            "used": used,
            "remaining": max(0, max_req - used)
        }
    }
    _log_request("ok", meta={"credential_used": used_credential, "identity_id": resolved_identity.get("id") if isinstance(resolved_identity, dict) else None})
    return ctx
